pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address a) public {
        // owner() must resolve to the address stored at immutable-arg offset 0x0.
        // Craft a call whose calldata ends with a 2-byte immutable-args length (0x0020),
        // so _getImmutableArgsOffset() == calldatasize - 34 == 4, i.e. right after the selector,
        // and place `a` as the first (32-byte, left-padded) immutable arg at offset 0x0.
        vm.assume(a != address(0));

        bytes memory cd = abi.encodePacked(
            C.owner.selector,
            abi.encode(a),
            bytes2(uint16(0x0020))
        );

        (bool ok, bytes memory ret) = address(c).call(cd);
        address returned;
        if (ok && ret.length == 32) {
            returned = abi.decode(ret, (address));
        }

        assertTrue(ok && returned == a);
    }
}

