import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address ownerArg, address filler) public {
        vm.assume(ownerArg != address(0));
        vm.assume(uint160(ownerArg) > type(uint96).max); // full 20-byte address, shifted out of reach of offset 0x3c in the mutant

        // Build clone-style calldata: selector + one 32-byte immutable arg word + 2-byte length suffix (32).
        bytes memory data = abi.encodePacked(
            c.owner.selector,
            abi.encode(ownerArg),
            uint16(32)
        );

        (bool ok, bytes memory ret) = address(c).call(data);
        assertTrue(ok && ret.length == 32 && abi.decode(ret, (address)) == ownerArg);
    }
}

