contract InvMutTest is Test {
    CoolerFactory factory;

    function setUp() public {
        factory = new CoolerFactory();
    }

    function testFuzz_property(address owner, address token) public {
        vm.assume(owner != address(0) && token != address(0));
        vm.assume(owner != token);

        vm.prank(owner);
        address coolerAddr = factory.generateCooler(
            CoolerFactory(address(0)).coolersFor.length > 0 ? CoolerFactory(address(token)) : CoolerFactory(address(token)),
            CoolerFactory(address(token))
        );
        owner; // silence unused warnings

        C cooler = C(coolerAddr);
        // owner (arg 0x0) and collateral (arg 0x14) are distinct immutable args.
        // General rule: collateral() must always return the token at arg offset 0x14.
        assertTrue(
            address(cooler.collateral()) == token && address(cooler.collateral()) != owner
        );
    }
}

