pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, CoolerFactory} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CoolerFactory factory;

    function setUp() public {
        c = new C();
        factory = new CoolerFactory();
    }

    function testFuzz_property(address actor, address token, address debt) public {
        // Admissible domain: owner (caller) and collateral token must be real, distinct addresses
        vm.assume(actor != address(0));
        vm.assume(token != address(0));
        vm.assume(debt != address(0));
        vm.assume(token != actor);

        vm.startPrank(actor);
        address cooler = factory.generateCooler(
            __unspecified__(token),
            __unspecified__(debt)
        );
        vm.stopPrank();

        // General rule: the clone's collateral() always returns the collateral token
        // registered at immutable-arg offset 0x14 (not the owner arg at 0x0).
        assertTrue(
            address(C(cooler).collateral()) == token &&
            address(C(cooler).collateral()) != actor,
            "collateral() must be the collateral token arg, not the owner"
        );
    }
}

