pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address owner, address token) public {
        // Admissible domain: owner and token are distinct non-zero addresses.
        vm.assume(owner != address(0));
        vm.assume(token != address(0));
        vm.assume(owner != token);

        // Emulate a clone's immutable-args layout: selector, then packed args
        // owner (arg@0x0, 20B), token (arg@0x14, 20B), then 2-byte args length 80.
        // _getImmutableArgsOffset() = calldatasize - len - 2 = 86 - 80 - 2 = 4,
        // so offset 0x0 -> owner, offset 0x14 -> token.
        bytes memory data = abi.encodePacked(
            C.collateral.selector,
            bytes20(owner),
            bytes20(token),
            bytes2(uint16(80))
        );

        (bool ok, bytes memory ret) = address(c).call(data);
        address returned;
        if (ok) {
            returned = abi.decode(ret, (address));
        }

        // General rule: collateral() always returns the immutable arg at 0x14 (token),
        // never the owner arg at 0x0. Reference holds for every admissible input;
        // the mutant returns owner != token and breaks it.
        assertTrue(ok && returned == token);
    }
}

