pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, CoolerFactory} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CoolerFactory factory;

    function setUp() public {
        c = new C();
        factory = new CoolerFactory();
    }

    function testFuzz_property(address collAddr, address debtAddr) public {
        // keep inputs in the admissible domain: token addresses must not collide
        // with the factory or the cooler-to-be, and must be non-zero
        vm.assume(collAddr != address(0));
        vm.assume(debtAddr != address(0));
        vm.assume(collAddr != address(factory));
        vm.assume(debtAddr != address(factory));
        vm.assume(collAddr != debtAddr);

        // generate a cooler (a C clone with immutable args) for the fuzzed pair
        vm.prank(address(this));
        address cooler = factory.generateCooler(
            C(std).collateralType(collAddr),
            C(std).collateralType(debtAddr)
        );

        // the cooler must be registered as created by the factory
        assertTrue(factory.created(cooler));

        // GENERAL RULE: the generated cooler's public collateral() getter returns
        // exactly the collateral token supplied at generation time.
        assertTrue(C(cooler).collateral() == C(std).collateralType(collAddr));
    }
}

// tiny helper to cast a raw address to the ERC20 alias used by the factory
contract Std {
    function collateralType(address a) external pure returns (address) {
        return a;
    }
}

contract std is Std {}
